package ru.bububu.radio.core;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
import ru.bububu.radio.sources.*;

public final class FirstAirProductTest {
    static NoteBook book(List<SourceProfiles45.Profile> profiles){List<SourceRecord> sources=new ArrayList<>();Map<String,String> ids=new TreeMap<>();for(SourceProfiles45.Profile p:profiles){sources.add(p.seed());ids.put(p.id,p.seed().id);}byte[] image=NoteBook.fresh45Target(sources,new Seed45Marker("01234567-89ab-4cde-8fab-0123456789ab",Seed45Marker.POLICY,SourceProfiles45.definitionSetHash(),ids));return new NoteBook(new NoteBook.Storage(){byte[] b=image;public byte[] load(){return b.clone();}public void save(byte[] v){b=v.clone();}});}
    @Test public void freshSixHasNoImplicitSamplesOrMaterials(){NoteBook b=book(SourceProfiles45.six());List<Station> stations=OrdinaryRadio.catalog(b);assertEquals(6,stations.size());for(Station station:stations){assertFalse(OrdinaryRadio.builtin(station.id));assertTrue(station.articles.isEmpty());}assertTrue(b.materials().isEmpty());assertTrue(b.notes().isEmpty());}
    @Test public void oldSampleProgressIsRetainedWithoutSelectingSample(){PlayerController.SavedProgress old=new PlayerController.SavedProgress("A","A1","1",0,false,List.of(0,1),false,true);PlayerController.SavedState prior=new PlayerController.SavedState("A",Map.of("A","A1"),Map.of(PlayerController.progressKey("A","A1","1"),old));PlayerController.SavedState current=new PlayerController.SavedState("SRC:real",Collections.emptyMap(),Collections.emptyMap());PlayerController.SavedState merged=OrdinaryRadio.preserveLegacy(current,prior);assertEquals("SRC:real",merged.currentStationId);assertSame(old,merged.progress.get(PlayerController.progressKey("A","A1","1")));assertEquals("A1",merged.stationArticleIds.get("A"));}
    @Test public void manualNoteRemainsInOrdinaryQueue(){NoteBook b=book(SourceProfiles45.six());b.addSavedMaterial(NoteBook.MY_TEXTS,"Мои тексты",Article.fromSentences("note-material","1","Свой текст","Моя заметка."));assertTrue(OrdinaryRadio.catalog(b).stream().anyMatch(s->s.id.equals(NoteBook.MY_TEXTS)&&s.articles.size()==1));}
    @Test public void approvedLegacyDefaultAddsNewsWithoutRemovingAnything(){NoteBook b=book(SourceProfiles45.legacySix());b.enable45();String attempt=b.seed45Marker().attemptId;b.beginRecording("Существующая заметка",null,null,null,1);Set<String> chosen=SourceDefaults45.upgradeLegacyStarter(b);assertNotNull(chosen);assertEquals(6,chosen.size());assertEquals(10,b.sources().size());assertEquals(1,b.notes().size());assertEquals(attempt,b.seed45Marker().attemptId);for(SourceProfiles45.Profile p:SourceProfiles45.legacySix())assertNotNull(b.source(p.seed().id));assertEquals(chosen,SourceDefaults45.upgradeLegacyStarter(b));}
    @Test public void disabledLegacyStationPreventsDefaultOverride(){NoteBook b=book(SourceProfiles45.legacySix());b.enable45();SourceRecord first=b.sources().get(0);b.updateSource(first.withState(false,null,null,0,null));assertNull(SourceDefaults45.upgradeLegacyStarter(b));assertEquals(6,b.sources().size());assertFalse(b.source(first.id).enabled);}
    @Test public void explicitSelectionAndNonDefaultAddedSourcesAreNeverOverridden(){NoteBook b=book(SourceProfiles45.legacySix());b.enable45();assertFalse(SourceDefaults45.mayUpgradeStarter(b,true,false));assertTrue(SourceDefaults45.mayUpgradeStarter(b,false,false));b.commitSource(SourceProfiles45.byId("rg-briefs").seed(),Collections.emptyList());assertFalse(SourceDefaults45.mayUpgradeStarter(b,false,false));assertTrue(SourceDefaults45.mayUpgradeStarter(b,false,true));}
    @Test public void progressMeansProcessedNotSuccessAndCancelDoesNotFake100(){assertEquals(50,DownloadPresentation.percent(3,6,false,false,false));assertEquals(99,DownloadPresentation.percent(6,6,false,false,false));assertEquals(100,DownloadPresentation.percent(6,6,true,false,false));assertEquals(50,DownloadPresentation.percent(3,6,true,true,false));assertEquals(33,DownloadPresentation.percent(2,6,true,false,true));assertEquals(0,DownloadPresentation.percent(0,0,false,false,false));}
}
